{
  "concepts_used": ["GC-0036", "GC-0072", "GC-0058", "GC-0001", "GC-0002", "GC-0038", "GC-0041", "GC-0013", "GC-0014", "GC-0029", "GC-0015"],
  "decline_reason": "",
